اللهم يا مُقلِّبَ القلوبِ ثبِّت قلبي على دينِك
قُلوب العِبادِ بين يَديِ الله عز وجل يُقلِّبها كيفَ يَشاء، ولذلك كان أكثر دعاء النَّبيِّ صلى الله عليه وسلَّم: "
يا
مُقلِّبَ القلوبِ، ثَبِّتْ قلبي على دِينِك
"، وذلك طلَبًا للثَّبات على الدِّين والطاعة، وخوفًا مِن الزَّيغِ أو الضلال.. وهذا يُبيِّنُ شِدَّةَ خوف النبي صلى الله عليه وسلم مِن ربِّه عزَّ وجل، وشِدَّة حِرصِه على تَنبيهِ أُمَّتِه ألَّا يصِيبها غَفلةٌ عن مُراقَبة أعمالِهِم وخَواتيمِها.. والأحاديث والمواقف النبوية الدالة على ذلك كثيرة، ومنها:
1 ـ
عن
شهر بن حوشب
رضي الله عنه قال: قُلتُ
لأمِّ سلمة
: يا أمَّ المؤمنين، ما كانَ أَكْثرُ دعاءِ رسول اللَّه صلى اللَّه عليه وسلم إذا كان عندَك (في بيتك)؟ قالت: كان أَكْثر دعائِه:
يا مُقلِّبَ القلوب
ِ ثبِّت قلبي على دينِكَ
، قالت: فقُلتُ: يا رسول اللَّه ما أكثرُ دعاءك يا مقلِّبَ القلوبِ ثبِّت قلبي على دينِك؟! قال: يا
أمَّ سلمة
إنَّه لَيس آدميٌّ إلَّا وقلبُهُ بينَ أصبُعَيْن من أصابع اللَّه، فمَن شاءَ أقام، ومن شاء أزاغ.
فتلا
معاذٌ
: {
رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا
}(آل عمران:8) رواه
الترمذي
.
2 ـ
عن أم المؤمنين
عائشة
رضي الله عنها: (أنَّ رسول الله صلى الله عليه وسلم كان يُكثِر أنْ يقول:
يا مُقَلِّبَ القُلوبِ ثَبِّتْ قلبي على دِينِك وطاعَتِك
، فقالَتْ له
عائشة
: إنَّكَ تُكثِر أنْ تقول: يا مُقَلِّبَ القُلوبِ ثَبِّتْ قَلْبي على دِينِك وطاعَتِك، قال:
وما يُؤَمِّنِّي
(وأيُّ شيءٍ يجعلني لا أخاف ويُعطيني الأمان)
؟ وإنَّما قُلوب العِبادِ بَينَ إصْبَعَيِ الرَّحمن، إنَّه إذا أراد أنْ يَقلِبَ قَلب عَبدٍ قَلَبَه
) رواه
أحمد
.
3 ـ
عن
أنس بن مالك
رضي الله عنه قال: (كانَ رسولُ اللَّه صلى اللَّه عليه وسلم يُكثِرُ أن يقولَ:
يا مقلِّبَ القلوبِ ثبِّت قلبي على دينِكَ،
فقلتُ: يا نبيَّ اللَّهِ آمنَّا بِكَ وبما جئتَ بِهِ فَهل تخاف علينا؟ قال:
نعَم، إنَّ القلوب بين إصبعين من أصابع اللَّه يقلِّبها كيف شاء
) رواه الترمذي.. وفي رواية
للحاكم
عن
النواس بن سمعان
: (
ما مِن قَلْبٍ إلَّا بيْن إِصْبَعَين مِن أصابع الرحمن، إنْ شاء أقامَه، وإنْ شاءَ أزاغَه،
وكان رسول اللهِ صلى اللَّه عليه وسلم يقول:
اللَّهُمَّ يا مُقلِّبَ القلوبِ ثَبِّتْ قُلوبَنا على دِينِك
)..
4 ـ
عن
عبد الله بن عمرو
رضي الله عنه قال: (
إنَّ قُلُوبَ بَنِي آدَمَ كُلَّهَا بيْنَ إِصْبَعَيْنِ مِن أَصَابِعِ الرَّحْمَنِ، كَقَلْبٍ وَاحِدٍ، يُصَرِّفُهُ حَيْثُ يَشَاءُ،
ثُمَّ قالَ رَسُولُ اللهِ صلى اللَّه عليه وسلم:
اللَّهُمَّ مُصَرِّفَ القُلُوبِ صَرِّفْ قُلُوبَنَا علَى طَاعَتِك
) رواه
مسلم
.
قال الراغب في "المفردات": تقليب الشيء تغييره من حال إلى حال، والتقليب التصرف، وتقليب الله القلوب والبصائر صرفها من رأي إلى رأي".. وكان أكثَر دعاءٍ يدعو به النَّبي صلى اللَّه عليه وسلم ـ كما ذَكَر ذلك أصحابه وزوجاته ـ:
(
يا مُقلِّبَ القلوب
) أي: يا مَن بِيَدِك أمر القلوب، فأنت تُقلِّبُ أحوالَها كيفَما تَشاء بينَ الإيمان والكفر، وبين الطاعة والمعصية، وبينَ التَّنبُّه والغفلة، (
ثبِّتْ قلبي على دينِك
) أي: اجعَلْ قلبي ثابتًا على دينِك وطاعتِك ومَرضاتِك في كُلِّ ما تُحبُّه منَ الأَقوالِ والأَعمال والأَخلاق، ولا تجعَلْه يَنحَرِفُ عن دينك وطريق هدايتك.. فسألَتْه
عائشة
و
أم سلمة
و
أنس
رضي الله عنهم: لِمَ تُكثِرُ مِن هذا الدُّعاء يا رسول الله؟! فقال صلى اللَّه عليه وسلم: (
إنَّه ليس آدَميٌّ إلَّا وقَلبُه بين أُصبَعَينِ مِن أصابعِ الله
)، أي: كلُّ أحدٍ مِن بَني آدمَ قَلبُه بيَد الله عز وجل يتَصرَّف فيه كيفَما يشاء، (
فمن شاء أقام
) أي: فمن شاء اللهُ أقام قلبَه على الهدى، وثبَّتَه على الدِّينِ، (
ومَن شاء أزاغ
) أي: ومَن شاء اللهُ صرَف قلبَه عن الهدى إلى الزَّيغ والضلال، ولذلك لما سمع
معاذ
بنُ معاذِ بنِ نصرِ بنِ حسَّانَ التَّميميُّ
هذا الحديث النبو
ي
قرأ قول الله تعالى: {
رَبَّنَا لَا تُزِغْ قُلُوبَنَا بَعْدَ إِذْ هَدَيْتَنَا
}(آل عمران:8)، أي: يا ربِّ ثَبِّت قُلوبَنا على دينك وطاعتِك، ولا تَصرِفْها عن طَريقِك بعدَ هِدايَتِك لنا..
وفي هذه الأحاديث وما شابهها: بيان شدة خوف النبي صلى الله عليه وسلم مِن الله عز وجل، وحِرْصه على تَنبيه أُمَّته ألَّا يُصيبَها غَفلة عن عبادة الله وطاعته، والحَثُّ على الإكثار من الدُّعاءِ بالثَّباتِ على الدِّين والهدى، وفيها: أنَّ جميع قُلوب بَني آدم بيَدِ الله، إنْ شاء هَداها، وإن شاء أزاغها، وإثبات صفة الأصابع لله عز وجل كما يَلِيق به سبحانه..
قال
ابن حجر
في "فتح الباري": "وفي دعائه صلى الله عليه وسلم: (
يا مقلب القلوب ثبت قلبي على دينك)
إشارة إلى شمول ذلك للعباد حتى الأنبياء، ورفع توهم مَنْ يتوهم أنهم يُستثنون مِن ذلك، وخصَّ نفسه بالذِكر إعلاماً بأن نفسه الزكية إذا كانت مفتقرة إلى أنْ تلجأ إلى الله سبحانه، فافتقار غيرها ممن هو دونه أحق بذلك".
وقال
الهروي
في "مرقاة المفاتيح شرح مشكاة المصابيح": "وفيه إرشاد للأمة، والظاهر أن كل أحد من العباد كما أنه مفتقر إليه تعالى في الإيجاد؟ لا يستغني عنه ساعة من الإمداد.. (
يا مقلب القلوب
) أي: مصرفها تارة إلى الطاعة، وتارة إلى المعصية، (
ثبت قلبي على دينك
)، أي: اجعله ثابتا على دينك غير مائل عن الدين القويم، والصراط المستقيم، والخُلق العظيم.. قال
أنس
: (يا نبي الله آمنا بك) أي: بنبوتك، ورسالتك (وبما جئت به) من الكتاب والسُنة (فهل تخاف علينا؟): يعني أن قولك هذا ليس لنفسك، لأنك في عصمة من الخطأ والزلة خصوصا من تقلب القلب عن الدين والملة، وإنما المراد تعليم الأمة، فهل تخاف علينا من زوال
نعم
ة الإيمان، أو الانتقال من الكمال إلى النقصان؟ (قال:
نعم
): يعني أخاف عليكم (
إنّ القلوب بين أصبعين من أصابع الله
): وفي خبر
مسلم
: (
من أصابع الرحمن
)، والفرق أنه ابتدأ به ثمة فالرحمة سبقت الغضب، فناسب ذكر الرحمن، وهنا وقع تأييدا للخوف عليهم، فالمقام مقام هيبة وإجلال، فناسب ذِكر مقام الجلالة والإلهية المقتضية لأن يخص من شاء بما شاء من هداية أو ضلالة، (
يقلبها
) أي: القلوب (
كيف يشاء
) أي: يقلب على أي صفة شاءها"..
وقال الشيخ
ابن باز
: "فالمؤمن يسأل ربه الثبات على الإيمان والثبات على الحق، فالقلوب تتقلب وهي بين إصبعين من أصابع الله، هذا يجرى على ظاهره، يثبت لله الأصابع على الوجه اللائق بالله، وأن الله جل وعلا بيده تصريف الأمور، وتقليب القلوب كيف يشاء، هذا يُقلب فيرتد عن دينه، وهذا يقلب فيُسلم، وهذا يُقلب قلبه فيقع في المعاصي، فالقلوب بيد الله جل وعلا، هو الذي يصرفها كيف يشاء، والمؤمن يسأل ربه يقول: اللهم ثبت قلبي على دينك.. والله عز وجل يوصف بأن له أصابع، وله يد جل وعلا، على الوجه اللائق به سبحانه وتعالى، لا يشابه عباده، لا في اليد ولا في الأصابع ولا في الكلام، ولا في الرضا، ولا في الغضب ولا في غير ذلك، كما قال سبحانه: {لَيْسَ كَمِثْلِهِ شَيْءٌ وَهُوَ السَّمِيعُ البَصِيرُ}(الشورى:11)"..
فائدة:
1 ـ
قال
ابن عبد البر
: "أهل السُنة مُجْمِعون على الإقرار بالصفات الواردة كلها في القرآن والسُنة والإيمان بها". وقال
ابن تيمية
في "منهاج السنة النبوية": "ولهذا كان مذهب سلف الأمة وأئمتها أنهم يصفون الله عز وجل بما وصف به نفسه، وبما وصفه به رسوله، من غير تحريف ولا تعطيل، ومن غير تكييف ولا تمثيل، يثبتون له الأسماء والصفات".. وقول أهل السُنة في الأصابع لله تعالى كقولهم في اليدين والوجه وغير ذلك مِن الصفات، وهو الإثبات مع نفي مماثلة المخلوقات. وقد اتفق أئمة وعلماء السلف على إثبات صفة الأصابع لله عز وجل، استنادا للأحاديث النبوية الصحيحة الواردة في ذلك، مع تفويض علم كيفية ذلك إلى الله تعالى، دون التعرض لتأويلها. قال
أبو بكر بن خزيمة
في "التوحيد": "(باب إثبات الأصابع لله عَزَّ وجَلَّ)". وقال
ابن بطة
في "الإبانة": "باب الإيمان بأن قلوب العباد بين إصبعين من أصابع الرب تعالى بلا كَيف". وقال
الآجري
في "الشريعة": "باب الإيمان بأن قلوب الخلائق بين إصبعين من أصابع الرب عَزَّ وجَلَّ، بلا كَيْف". وقال
البغوي
في "شرح السُنة": "الإصبع المذكورة في الحديث صفة من صفات الله عز وجل، وكذلك كل ما جاء به الكتاب أو السُنة من هذا القبيل في صفات الله سبحانه وتعالى، كالنفس، والوجه، والعين، واليد، والرجل، والإتيان، والمجيء، والنُّزُول إلى السماء الدنيا، والاستواء على العرش، والضحك، والفرح". وقال ابن قتيبة في "تأويل مختلف الحديث": "ولا نقول: أصبع كأصابعنا، ولا يد كأيدينا، ولا قبضة كقبضاتنا، لأن كل شيء منه عز وجل لا يشبه شيئًا منا"..
2 ـ
أخبرنا النبي صلى الله عليه وسلم عن كون القلوب بين أصبعين من أصابع الرحمن، ولم يخبرنا عن كيفية ذلك، فنؤمن بما أخبرنا به، ونسكت عما لم يخبرنا عنه، ولا نتكلف ونقول على الله ما لا نعلم، والذي ينبغي على المسلم أن يكون اهتمامه في هذه الأحاديث ونحوها بما يصلح قلبه، والخشية على نفسه الضلال بعد الهدى، داعياً وسائلاً ربَّه سبحانه أن يثبت قلبه على الدين والهُدى..
لقد كان رسول صلى الله عليه وسلم، الذي غفر الله له ما تقدم من ذنبه وما تأخر، والمؤيَّد بالوحي، ولا ينطق عن الهوى، يُكثر مِن دعائه وسؤاله لربه سبحانه أنْ يثبت قلبه على دينه، ومن ثم، يجب على المسلم أن يكون شديد الخوف من الله، وألا يأمن على نفسه، فالله يفعل ما يشاء، يهدي مَنْ يشاء ويضل منْ يشاء، ويرفع مَن يشاء ويخفض من يشاء.. واقتداء بنبينا صلى الله عليه وسلم، علينا الإكثار من دعائنا لله عز وجل بدعائه الذي كان يُكثر منه: (
اللهم يا مُقلِّبَ القلوبِ ثبِّت قلبي على دينِك
)..
