49
11/01/2026
https%3A%2F%2Fwww.islamweb.net%2Far%2Farticle%2F224149%2F%D8%A5%D9%90%D8%AE%D9%92%D8%A8%D9%8E%D8%A7%D8%B1-%D8%A7%D9%84%D9%8A%D9%87%D9%88%D8%AF-%D8%B9%D9%86-%D8%A7%D9%84%D9%86%D8%A8%D9%8A%D9%91%D9%90-%D9%88%D8%A8%D8%B9%D8%AB%D8%AA%D9%87
تم نسخ الرابط
5
الكاتب:
إسلام ويب
التصنيف:
آيات ومعجزات النبوة
إِخْبَار اليهود عن النبيِّ وبعثته
أخبار اليهود بقُرْبِ بعثة نبي اقترب زمانه انتشرت فى يثرب (المدينة المنورة)، وانتقلت إلى أهلها من جيل إلى جيل، وكان ذلك من أسباب مسارعة الأنصار للاستجابة للنبى صلى الله عليه وسلم والإيمان به.
ذكر
ابن هشام
وغيره في السيرة النبوية عن
عاصم بن عمرو بن قتادة
عن رجال من قومه قالوا: "إن مما دعانا إلى الإِسلام ـ مع رحمة الله تعالى وهداه لنا ـ: أن كنا نسمع من رجل من اليهود وكنا أهل شرك أصحاب أوثان، وكانوا أهل كتاب عندهم علم ليس لنا، وكانت لا تزال بيننا وبينهم شرور، فإذا نلنا منهم بعض ما يكرهون قالوا لنا: إنه قد تقارب زمان نبي يبعث الآن نقتلكم معه قتل عاد وإرم. فكنا كثيرًا ما نسمع ذلك منهم، فلما بعث الله رسول الله صلى الله عليه وسلم أجبناه حين دعانا إلى الله وعرفنا ما كانوا يتواعدوننا به فبادرناهم إليه فآمنا به وكفروا به، ففينا وفيهم نزلت هذه الآية: {
وَلَمَّا جَاءَهُمْ كِتَابٌ مِنْ عِنْدِ اللَّهِ مُصَدِّقٌ لِمَا مَعَهُمْ وَكَانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جَاءَهُمْ مَا عَرَفُوا كَفَرُوا بِهِ فَلَعْنَةُ اللَّهِ عَلَى الْكَافِرِينَ
}(البقرة: 89).
قال
ابن كثير
في تفسيره:" يقول تعالى: {
وَلَمَّا جَاءَهُمْ
} يعني اليهود {
كِتَابٌ مِنْ عِنْدِ اللَّهِ
} وهو: القرآن الذي أنزل على
محمد
صلى الله عليه وسلم {
مُصَدِّقٌ لِمَا مَعَهُمْ
} يعني: من التوراة، وقوله: {
وَكَانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا
} أي: وقد كانوا من قبل مجيء هذا الرسول بهذا الكتاب يستنصرون بمجيئه على أعدائهم من المشركين إذا قاتلوهم، يقولون: إنه سيُبْعَث نبي في آخر الزمان نقتلكم معه قتل عاد وإرم .. قالوا (مِن الأنصار): كنا قد علوناهم دهرا في الجاهلية، ونحن أهل شرك وهم أهل كتاب، فكانوا يقولون: إن نبياً من الأنبياء يبعث الآن نتبعه، قد أظل زمانه، نقتلكم معه قتل عاد وإرم. فلما بعث الله رسوله من قريش واتبعناه كفروا به".
وعن
عبد الله بن عباس
رضي الله عنه: (أنَّ يهودَ كانوا يستَفتحون على الأوس والخزرج برسول الله صلى الله عليه وسلم قبل مبعثه، فلمَّا بعثه الله منَ العرب كفروا بِه وجحدوا ما كانوا يقولون فيه، فقال لهم
معاذ بن جبلٍ
و
بِشْر بن البراء بنِ معرورٍ
و
داود بن سلمة
: يا معشر يهود، اتَّقوا اللَّهَ وأسلِموا، فقد كنتُمْ تستَفتِحون علينا ب
محمَّدٍ
صلى الله عليه وسلم ونحن أهْل شركٍ وتخبروننا بأنَّه مبعوث وتصفونه لنا بصفته، فقال
سلَّام بن مشكَمٍ
أخو بني النَّضير: ما جاءَنا بشيءٍ نعرفه، وما هو بالذي كنَّا نذكر لكم، فأنزل اللَّهُ في ذلك: {
وَلَمَّا جَاءَهُمْ كِتَابٌ مِنْ عِنْدِ اللهِ مُصَدِّقٌ لِمَا مَعَهُمْ وَكَانُوا مِنْ قَبْلُ يَسْتَفْتِحُونَ عَلَى الَّذِينَ كَفَرُوا فَلَمَّا جَاءَهُمْ مَا عَرَفُوا كَفَرُوا بِهِ فَلَعْنَةُ اللهِ عَلَى الكَافِرِينَ
}(البقرة:89)).
والسيرة النبوية سجلت مواقف وأحداث تدل على عِلْمِ وإِخْبَارِ اليهود ببعثة ونبوة نبينا
محمد
صلى الله عليه وسلم، ومن ذلك:
ـ
ذكر ابن هشام
في السيرة النبوية، و
البيهقي
في دلائل النبوة، و
السيوطي
في الخصائص الكبرى وغيرهم عن
سلمة بن سلامة بن وَقْشٍ
رضي الله عنه وكان من أصحاب بدر قال: (كان لنا جار يهودي من يهود بني عبد الأشهل فخرج علينا يوماً من بيته قبل مبعث النبي بيسير فوقف على المجلس قال
سلمة
: وأنا يومئذ أحدث من فيه سنًا (أصغرهم) عليّ بردة مضطبعاً فيها، فذكر البعث والقيامة والحساب والميزان والجنة والنار، فقال ذلك لقوم أهل شرك وأصحاب أوثان لا يرون أن بعثًا كائن بعد الموت، فقالوا: ويحك يا فلان، ترى هذا كائِناً؟ قال: نعم، قالوا: ويحك وما آية (علامة) ذلك؟ قال: نبي يُبْعَث من نحو هذه البلاد وأشار بيده نحو مكة واليمن، قالوا: ومتى تراه؟ قال: فنظر إِليّ فقال: إِنْ يَسْتَنْفِذْ هَذَا الْغُلَامُ عُمُرَه يُدْرِكْه، قال:
سلمة
: فوالله ما ذهب الليل والنهار حتى بعث الله تعالى رسوله صلى الله عليه وسلم وهو حي بين أظهرنا ـ يعني اليهودي ـ، فآمنَّا به وكفر به بَغْياً وحسدا".
ـ
في قصة إسلام حبر اليهود
عبد الله بن سلام
رضي الله عنه شاهد على عِلْمِ اليهود بالنبي صلى الله عليه وسلم وبعثته. فعن
أنس بن مالك
رضي الله عنه: (أن
عبد الله بن سلام
بلغه مقدم النبي صلى الله عليه وسلم المدينة، فأتاه يسأله عن أشياء، فقال: إني سائلك عن ثلاث (ثلاث مسائل) لا يعلمهن إلا نبي: ما أول أشراط (علامات) الساعة؟ وما أول طعام يأكله أهل الجنة؟ وما بال الولد ينزع إلى أبيه أو إلى أمه؟ قال:
أخبرني به
جبريل
آنفا،
قال
ابن سلام
: ذاك عدو اليهود من الملائكة، قال صلى الله عليه وسلم:
أما أول أشراط الساعة: فنار تحشرهم من المشرق إلى المغرب، وأما أول طعام يأكله أهل الجنة: فزيادة كبد الحوت، وأما الولد: فإذا سبق ماء الرجل ماء المرأة نزع الولد
(يشبه أباه)
، وإذا سبق ماء المرأة ماء الرجل نزعت الولد،
قال: أشهد أن لا إله إلا الله وأنك رسول الله، قال: يا رسولَ الله، إن اليهود قوم بُهُت (كذابون لا يرجعون إلى الحق)، فاسألهم عني قبل أن يعلموا بإسلامي، فجاءت اليهود، فقال النبي صلى الله عليه وسلم:
أي رجل
عبد الله بن سلام
فيكم؟!
قالوا: خيرنا وابن خيرنا، وأفضلنا وابن أفضلنا، فقال النبي صلى الله عليه وسلم:
أرأيتم إن أسلم
عبد الله بن سلام
؟
!
قالوا: أعاذه الله من ذلك، فأعاد عليهم فقالوا مثل ذلك، فخرج إليهم
عبد الله
فقال: أشهد أن لا إله إلا الله وأن
محمدا
رسول الله، قالوا: شرُّنا وابن شرِّنا، وتنقَّصُوه (انتقصوا منه وعابوه)، قال: هذا كنتُ أخاف يا رسولَ الله) رواه
البخاري
.
ـ
زَيْدُ بْنُ سَعْنَة
: قال
ابن عبد البر
عنه: "كان من أحبار يهود، أسلم وشهد مع النبي صلى الله عليه وسلم مشاهد كثيرة". وقصة إسلامه فيها دلالة على معرفته ببعض صفات النبي الذي ينتظر اليهود بعثته، والتي رآها متحققة وموجودة في النبي صلى الله عليه وسلم، والتي منها: (لا تزيده شدة الجهل عليه إلا حلما).
عن
عبد الله بن سلام
رضي الله عنه قال: (أن الله لما أراد هُدَى
زيد بن سعنة
قال زيد: لم يبق شيء من علامات النبوة إلا وقد عرفتها في وجه
محمد
صلى الله عليه وسلم حين نظرت إليه إلا اثنتين لم أُخْبَرْهُما منه: يسبق حلمه جهله، ولا تزيده شدة الجهل عليه إلا حلما، قال: فكنت أتلطف له لأن أخالطه فأعرف حلمه وجهله) فذكر قصة إسلافه للنبي صلى الله عليه وسلم مالا، قال: (فلما حلَّ الأجل أتيته فأخذت بمجامع قميصِهِ وردائِه وهو في جنازة مع أصحابه، ونظرت إليه بوجه غليظ، وقلت: يا
محمد
ألا تقضيني حقي؟! فو الله ما علمتكم
بني عبد المطلب
إلا مطلا، ونظرت إلى
عمر
وعيناه تدوران في وجهه كالفلك المستدير، ثم رماني ببصره وقال: يا عدو الله أتقول لرسول الله صلّى الله عليه وسلم ما أسمع وتصنع به ما أرى؟ فلولا ما أحاذر لومه ضربت بسيفي رأسك، ورسول الله صلى الله عليه وسلم ينظر إلى
عمر
في سكون وتؤدة، وقال:
أنا وهو كنا أحوج إلى غير ذلك منك يا
عمر
، أن تأمرنى بحسن الأداء، وتأمره بحسن اتباعه، اذهب به يا عمر فاقبضه حقه، وزد عشرين صاعاً من تمر، فأسلم (
زَيْدُ بْنُ سَعْنَة
)
) رواه
الطبراني
و
اب
ن حبان
وغيرهما، وقال
الهيثمي
في المجمع
وابن حجر
في الإصابة: رجاله ثقات، وضَعَّفَه بعض العلماء.
لم تكن تلك المعرفة لليهود ببعثة وصفات نبينا
محمد
صلى الله عليه وسلم إلا نتيجة النبوءات والصفات والشمائل التي كانت موجودة في التوراة ـ قبل تحريفها ـ، والتي وُصِف النبي صلى الله عليه وسلم من خلالها وصفاً دقيقاً في خَلْقِه وخُلُقِه. فعن
عطاء بن يسار
رضي الله عنه قال: لقيت
عبد الله بن عمرو بن العاص
رضي الله عنه قلتُ: (أخبرني عن صفة رسول الله صلى الله عليه وسلم ـ في التوراة، قال: أجل، والله إنه لموصوف ببعض صفته في القرآن: {
يَا أَيُّهَا النَّبِيُّ إِنَّا أَرْسَلْنَاكَ شَاهِداً وَمُبَشِّراً وَنَذِيراً
}(الأحزاب:45) وحِرْزاً للأميين، أنت عبدي ورسولي، سميتك المتوكل ليس بفظ ولا غليظ ولا سخاب في الأسواق، ولا يدفع بالسيئة السيئة، ولكن يعفو ويغفر، ولن يقبضه الله حتى يقيم به الملة العوجاء، بأن يقولوا: لا إله إلا الله، ويفتح به أعينا عميا، وآذانا صما، وقلوبا غلفا) رواه
البخاري
.
وقد وصف الله عز وجل معرفة اليهود بالنبي صلى الله عليه وسلم بأنها معرفة تضاهي وتشابه معرفتهم بأبنائهم فقال سبحانه: {
الَّذِينَ آَتَيْنَاهُمُ الكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ وَإِنَّ فَرِيقًا مِنْهُمْ لَيَكْتُمُونَ الحَقَّ وَهُمْ يَعْلَمُونَ
}(البقرة:146)، قال
ابن كثير
: "يخبر تبارك وتعالى أن علماء أهل الكتاب يعرفون صحة ما جاءهم به الرسول صلى الله عليه وسلم {
يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ
} كما يعرف أحدهم ولده، والعرب كانت تضرب المثل في صحة الشيء بهذا". وقال
القرطبي
: "قوله تعالى:" {
الَّذِينَ آَتَيْنَاهُمُ الكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ
} أي يعرفون نبوته وصدق رسالته، والضمير عائد على
محمد
صلى الله عليه وسلم، قاله
مجاهد وقتادة
وغيرهما.. وخصَّ الأبناء في المعرفة بالذِكْرِ دون الأنفس وإن كانت ألصق لأن الإنسان يمر عليه من زمنه برهة لا يعرف فيها نفسه، ولا يمر عليه وقت لا يعرف فيه ابنه. وروي أن
عمر
قال ل
عبد الله بن سلام
: أتعرف
محمداً
صلى الله عليه وسلم كما تعرف ابنك؟ فقال: نعم وأكثر، بعث الله أمينه في سمائه إلى أمينه في أرضه بنعته (بوصفه) فعرفته.. قوله تعالى: {
وَإِنَّ فَرِيقًا مِنْهُمْ لَيَكْتُمُونَ الحَقَّ
} يعني
محمداً
صلى الله عليه وسلم، قاله
مجاهد وقتادة
.. قوله تعالى:{
وَهُمْ يَعْلَمُونَ
} ظاهر في صحة الكفر عنادا، ومثله: {
وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنْفُسُهُمْ
}(النمل:14)، وقوله: {
فَلَمَّا جَاءَهُمْ مَا عَرَفُوا كَفَرُوا بِهِ
}(البقرة:89)".
