            "font-size": 25,
            'fill': 5
        }).radialProgress("to", { 'perc': 75, 'time': 1000 });

        $('.panel').hide();
        $('.tab').hide();
        if ($(window).width() > 768) {
            if ($(".islamweb-font").css('marginRight') == "0px") {
                CloseQuickHelpPanel();
            }
            else {
                OpenQuickHelpPanel();
            }
        } else {
            $('.quick-help-panel').show();
        }

    });


