".. وقد قال الله تعالى: {
قُلْ إِنْ كَانَ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ وَإِخْوَانُكُمْ وَأَزْوَاجُكُمْ وَعَشِيرَتُكُمْ وَأَمْوَالٌ اقْتَرَفْتُمُوهَا وَتِجَارَةٌ تَخْشَوْنَ كَسَادَهَا وَمَسَاكِنُ تَرْضَوْنَهَا أَحَبَّ إِلَيْكُمْ مِنَ اللَّهِ وَرَسُولِهِ وَجِهَادٍ فِي سَبِيلِهِ فَتَرَبَّصُوا حَتَّى يَأْتِيَ اللَّهُ بِأَمْرِهِ وَاللَّهُ لا يَهْدِي الْقَوْمَ الْفَاسِقِينَ
}(التوبة:24). قال القاضي
عياض
عن هذه الآية: "فكفى بهذا حضاً وتنبيها ودلالة وحجة على إلزام محبته، ووجوب فرضها، وعظم خطرها، واستحقاقه لها صلى الله عليه وسلم، إذ قرَّع - سبحانه - مَنْ كان ماله وأهله وولده أحب إليه من الله ورسوله، وأوعدهم بقوله تعالى: {
فَتَرَبَّصُوا حَتَّى يَأْتِيَ اللَّهُ بِأَمْرِهِ
}، ثم فسَّقهم بتمام الآية، وأعلمهم أنهم ممن ضل ولم يهده الله".
ومحبة النبي صلى الله عليه وسلم الحقيقية ليست مجرد كلمات يرددها اللسان، ولا يكفي فيها الادعاء والقول فحسب، بل لا بد أن تكون محبته ـ عليه الصلاة والسلام ـ حياة تُعاش، ومنهجاً يُتبع، قال الله تعالى: {
قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ
}(آل عمران:31). قال
الحسن البصري
وغيره من السلف: "زعم قوم أنهم يحبون الله فابتلاهم الله بهذه الآية فقال: {
قُلْ إِن كُنتُمْ تُحِبُّونَ اللّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللّهُ
}(آل عمران:31)". وقد تغير مفهوم محبة النبي صلى الله عليه وسلم الحقيقية وانحرف عند البعض، فبعد أن كانت هذه المحبة تعني طاعته واتباعه، صار مفهومها عندهم تأليف الصلوات المُبْتَدَعة، وعمل الموالد، وإنشاد القصائد والمدائح والني في بعضها الاستغاثة به، والغلو فيه بإخراجه عن حد البشرية..
ومحبة النبي صلى الله عليه وسلم الصادقة لها دلائل وصور ومظاهر كثيرة، منها:
1 ـ
تعزيره وتوقيره:
مِن دلائل وصور محبته صلى الله عليه وسلم تعزيره وتوقيره، كما قال الله تعالى: {
لِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ وَتُعَزِّرُوهُ
وَتُوَقِّرُوهُ
}(الفتح:9). قال
ابن كثير
: "{
لِتُؤْمِنُوا بِاللَّهِ وَرَسُولِهِ وَتُعَزِّرُوهُ
} قال
ابْن عَبَّاسٍ
وَغَيْر وَاحِدٍ: يُعَظِّمُوه، {وَتُوَقِّرُوهُ} مِنَ التَّوْقِير وهو الِاحْتِرَام وَالْإِجْلَال وَالْإِعْظَام". وقال
السعدي
: "{
وَتُعَزِّرُوهُ وَتُوَقِّرُوهُ
} أي: تعزروا الرسول صلى الله عليه وسلم وتوقروه أي: تعظموه وتجلوه، وتقوموا بحقوقه". وقال
ابن تيمية
: "التعزير اسم جامع لنصره وتأييده ومنعه مِنْ كل ما يؤذيه، والتوقير: اسم جامع لكل ما فيه سكينة وطمأنينة من الإجلال، وأن يعامل من التشريف والتكريم والتعظيم بما يصونه عن كل ما يخرجه عن حد الوقار". وقال ـ
ابن تيمية
ـ: "إن قيام المدحة والثناء عليه صلى الله عليه وسلم والتعظيم والتوقير له قيام الدين كله وسقوط ذلك سقوط الدين كله".
2 ـ طاعته واتباعه:
مِن دلائل ومظاهر حب النبي صلى الله عليه وسلم: طاعته فيما أمر به، واجتناب ما نهى عنه، واتباعه والاقتداء به، والتأسي بسنته ظاهرا وباطنا، والتمسك بها والحرص عليها، والدعوة إليها، وتحكيم ما جاء به صلى الله عليه وسلم في الأمور كلها، والسعي في إظهار دينه، ونصر ما جاء به، قال الله تعالى: {
قُلْ إِن كُنتُمْ تُحِبُّونَ اللّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللّهُ
}(آل عمران:31) قال
السعدي
: "أي: ادعيتم هذه المرتبة العالية، والرتبة التي ليس فوقها رتبة فلا يكفي فيها مجرد الدعوى، بل لا بد من الصدق فيها، وعلامة الصدق اتباع رسوله صلى الله عليه وسلم في جميع أحواله، في أقواله وأفعاله، في أصول الدين وفروعه، في الظاهر والباطن". وقال القاضي
عياض
: "اعلم أن مَنْ أحب شيئا آثره وآثر موافقته، وإلا لم يكن صادقا في حبه وكان مدعيا، فالصادق في حب النبي ـ صلى الله عليه وسلم ـ مَنْ تظهر علامة ذلك عليه، وأولها الاقتداء به واستعمال سنته، واتباع أقواله وأفعاله، وامتثال أوامره واجتناب نواهيه، والتأدب بآدابه في عسره ويسره ومنشطه ومكرهه، وشاهد هذا قوله تعالى: {
قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ وَاللَّهُ غَفُورٌ رَحِيمٌ
}(آل عمران:31)".
3 ـ التمسك بسنته:
مِن دلائل ومظاهر حب للنبي صلى الله عليه وسلم التمسك بسنته والدعوة إليها، والحذر مِن الابتداع في دين الله عز وجل. عن
عائشة
رضي الله عنها قالت: قال رسول الله صلى الله عليه وسلم: (
مَنْ أحدث في أمرنا هذا ما ليس منه فهو رد
) رواه
البخاري
. وعن
أبي رافع
رضي الله عنه قال: قال رسول الله صلى الله عليه وسلم ـ: (
لا أَلفِينَّ أحدكم مُتكِئًا على أريكته، يأتيه الأمر من أمري، مما أمرتُ به، أو نهيت عنه، فيقول: لا أدري ما وجدنا في كتاب الله اتبعناه، ألا وإني أوتيت الكتاب ومثله معه
) رواه
أحمد
وصححه
الألباني
. قال
ابن حبان
: "إن في لزوم سنته صلى الله عليه وسلم تمام السلامة، وجماع الكرامة، لا تطفأ سُرُجها، ولا تدحض حججها، مَنْ لزمها عُصِم، ومَنْ خالفها يُذم، إذ هي الحصن الحصين، والركن الركين، الذي بان فضله، ومتن حبله، مَنْ تمسك بها ساد، ومَن رام خلافه باد، فالمتعلقون بها أهل السعادة في الآجل، والمُغْبَطون بين الأنام في العاجل".
4 ـ كثرة الصلاة عليه:
قال الله تعالى: {إِ
نَّ اللَّهَ وَمَلائِكَتَهُ يُصَلُّونَ عَلَى النَّبِيِّ يَا أَيُّهَا الَّذِينَ آمَنُوا صَلُّوا عَلَيْهِ وَسَلِّمُوا تَسْلِيماً
}(الأحزاب:56). وعن
عبد الله بن عمر
و رضي الله عنه أن النبي صلى الله عليه وسلم قال: (
مَن صَلَّى عَلَيَّ صَلاةً صَلَّى اللَّهُ عليه بها عَشْرًا
) رواه
مسلم
. ولهذا قال النبي صلى الله عليه وسلم: (
البخيلُ الَّذي مَن ذُكِرتُ عندَهُ فلم يصلِّ عليَّ
) رواه
الترمذي وصححه الألباني
. وقال
ابن القيم
في "جلاء الأفهام": "والمعنى أنه إذا كان الله وملائكته يصلون على رسول الله فصلوا أنتم أيضـًا عليه، فأنتم أحق بأن تصلوا عليه وتسلموا تسليما، لما نالكم ببركة رسالته ويُمْنِ سفارته، من خير شرف الدنيا والآخرة". وقال
النووي
في "الأذكار": "إذا صلى أحدكم على النبي صلى الله عليه وسلم - فليجمع بين الصلاة والتسليم، ولا يقتصر على أحدهما، فلا يقل: "صلى الله عليه" فقط، ولا "عليه السلام" فقط".
5 ـ حب الصحابة:
من دلائل ومظاهر حب النبي صلى الله عليه وسلم حب أصحابه ومعرفة فضلهم وقدرهم والثناء عليهم بما هم أهله، والانتصار لهم ممن يؤذيهم وبغير الخير يذكرهم، فهم خير هذه الأمة بعد نبيها، ويكفي أنهم فازوا بشرف صحبة النبي صلى الله عليه وسلم وأن الله قد خصهم بهذا الشرف دون غيرهم من العالمين، فكانت لهم منزلة الصحبة التي لا تعادلها أي منزلة سواها في هذه الأمة، وقد كان النبي صلى الله عليه وسلم لحبه لهم يوصي بهم وبحبهم، ويحذر من الإساءة لأحد منهم.
6 ـ التأدب معه ومع سنته:
مِن دلائل ومظاهر حب النبي صلى الله عليه وسلم: التأدب معه، فلا يُذكر اسمه مجرداً، بل يوصف بالنبوة أو الرسالة، فيقال: نبي الله، رسول الله، ونحو ذلك.  قال الله تعالى: {
لَا تَجْعَلُوا دُعَاءَ الرَّسُولِ بَيْنَكُمْ كَدُعَاءِ بَعْضِكُمْ بَعْضاً
}(النور:63). قال
ابن كثير
: "قال
الضحاك
عن
ابن عباس
: كانوا يقولون: يا
محمد
، يا
أبا القاسم
، فنهاهم الله عز وجل عن ذلك، إعظامًا لنبيه صلى الله وسلم عليه، فقالوا: يا رسول الله، يا نبي الله". وكان الإمام
مالك
إذا أراد أن يخرج يحدِّث عن النبي صلى الله عليه وسلم توضأ وضوءه للصلاة، ولبس أحسن ثيابه، ومشَّط لحيته، فقيل له في ذلك، فقال: "أوقّر به حديث رسول الله صلى الله عليه وسلم". وقال
ابن القيم
: "ومن الأدب معه صلى الله عليه وسلم ألا يُستشكَل قوله، بل تُستشكَل الآراء لقوله، ولا يُعارَض نصه بقياس، بل تُهدَر الأقيسة وتلقى لنصوصه، ولا يُحرف كلامه عن حقيقته لخيال يسميه أصحابه معقولاً". وكذلك من حبه صلى الله عليه وسلم الذَّبُّ والدفاع عن سنته، وذلك بحمايتها من انتحال المبطلين، وتحريف الغالين وتأويل الجاهلين، ورد شبهات الكاذبين..
7 ـ
ومِن دلائل محبتنا للنبي صلى الله عليه وسلم أن نتبعه في أخلاقه ومعاملاته، وأن نتعرف على معجزاته وفضائله وخصائصه التي خصه الله عز وجل بها لعلو قدره ومنزلته، ومعرفة ذلك تزيد المسلم حباً وتوقيراً، وأدباً واتباعاً له صلى الله عليه وسلم..
إن حب النبي صلى الله عليه وسلم عقيدة وإيمان، فلا يتم إيمان المسلم حتى يحبَّ النبيَّ صلى الله عليه وسلم، بل حتى يكون أحبَّ إليه مِن والده وولده ونفسه والناس أجمعين. قال
ابن تيمية
: "وأما السبب في وجوب محبته صلى الله عليه وسلم وتعظيمه أكثر من أي شخص فلأن أعظم الخير في الدنيا والآخرة لا يحصل لنا إلا على يد النبي صلى الله عليه وسلم بالإيمان به واتباعه، وذلك أنه لا نجاة لأحد من عذاب الله، ولا وصول له إلى رحمة الله إلا بواسطة الرسول، بالإيمان به ومحبته وموالاته واتباعه، وهو الذى ينجيه الله به من عذاب الدنيا والآخرة، وهو الذى يوصله إلى خير الدنيا والآخرة". والمحبة الحقيقية لنبينا صلى الله عليه وسلم لا يكفي فيها الادعاء باللسان فحسب، بل لا بد أن تكون محبته ـ صلوات الله وسلامه عليه ـ منهجاً يُتبع، وحياة تعاش، وأخلاقاً يُقْتدَى بها، ولذا جعل الله تعالى اتباعه صلى الله عليه وسلم علامة محبة العباد له سبحانه، فقال تعالى: {
قُلْ إِنْ كُنْتُمْ تُحِبُّونَ اللَّهَ فَاتَّبِعُونِي يُحْبِبْكُمُ اللَّهُ}
(آل عمران:31). قال
ابن كثير
: "هذه الآية الكريمة حاكمة على كل مَنِ ادَّعى محبة الله، وليس هو على الطريقة المحمدية فإنه كاذب في دعواه في نفس الأمر، حتى يتبع الشرع المحمدي والدين النبوي في جميع أقواله وأحواله". فحريٌّ بنا أن نحقق محبته صلى الله عليه وسلم اعتقاداً وقولاً وعملاً، ونقدمها على محبة النفس والولد والناس أجمعين، وأن يكون حبنا له حباً صادقاً بالقلب واللسان والجوارح، وذلك بحبه وتوقيره والأدب معه، وطاعته والاقتداء به، والتمسك بهديه وسنته ـ صلوات الله وسلامه عليه ـ..
