	  navigator.clipboard.writeText(dataUrl).then(() => {
    // Find the sibling feedback element using jQuery
    var feedback = $("#copystatus");

    if (feedback.length) {
      // Show feedback text
      feedback.css('display', 'inline'); // Use jQuery's CSS method

